public string State
        {
            get => string.IsNullOrEmpty(_state)
                ? ((LK_ViewState) StateId == LK_ViewState.U_u
                    ? null
                    : ((LK_ViewState) StateId).ToString().Split('_')[1].Trim().ToUpper())
                : _state;
            set
            {
                _state = value;
                StateId = string.IsNullOrEmpty(value)
                    ? (int) LK_ViewState.U_u
                    : (int) Enum.Parse(typeof(LK_ViewState), Util.Pascalize($"{CountryCode}_{value}"));  
            }
        }
